    <section
      class="typography-page-template__section typography-page-template__section--spaced"
    >
      <div class="sgds:flex sgds:flex-col sgds:gap-text-md">
        <SectionHeader title="Breakpoint tokens" />
        <p
          class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal sgds:m-0"
        >
          Breakpoints maintain layout integrity across screen sizes. Each
          breakpoint range determines the number of columns, recommended margins
          and gutters for each display size.
        </p>
      </div>
      <div
        class="typography-page-template__body typography-page-template__body--prose"
      >
        <div class="sgds:flex sgds:flex-col sgds:gap-layout-lg">
          <div class="sgds:flex sgds:flex-col sgds:gap-text-xs">
            <h3
              class="sgds:text-heading-sm sgds:font-semibold sgds:leading-sm sgds:tracking-tight sgds:m-0"
            >
              Standard breakpoint
            </h3>
            <sgds-table
              tableBorder
              headerBackground
              responsive="always"
              class="typography-page-template__utility-table"
            >
              <sgds-table-row>
                <sgds-table-head :class="tokenColumnClass"
                  >Token</sgds-table-head
                >
                <sgds-table-head :class="valueColumnClass"
                  >Screen size</sgds-table-head
                >
                <sgds-table-head :class="valueColumnClass"
                  >Container width</sgds-table-head
                >
                <sgds-table-head :class="numericColumnClass"
                  >Columns</sgds-table-head
                >
                <sgds-table-head :class="numericColumnClass"
                  >Gutters</sgds-table-head
                >
                <sgds-table-head :class="valueColumnClass"
                  >Outer margins</sgds-table-head
                >
              </sgds-table-row>

              <sgds-table-row v-for="row in breakpointTokens" :key="row.token">
                <sgds-table-cell :class="tokenColumnClass">
                  <CodeToken :label="`--${row.token}`" />
                </sgds-table-cell>
                <sgds-table-cell :class="valueColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.screenSize }}
                  </span>
                </sgds-table-cell>
                <sgds-table-cell :class="valueColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.containerWidth }}
                  </span>
                </sgds-table-cell>
                <sgds-table-cell :class="numericColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.columns }}
                  </span>
                </sgds-table-cell>
                <sgds-table-cell :class="numericColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.gutters }}
                  </span>
                </sgds-table-cell>
                <sgds-table-cell :class="valueColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.outerMargins }}
                  </span>
                </sgds-table-cell>
              </sgds-table-row>
            </sgds-table>
          </div>

          <div class="sgds:flex sgds:flex-col sgds:gap-text-xs">
            <h3
              class="sgds:text-heading-sm sgds:font-semibold sgds:leading-sm sgds:tracking-tight sgds:m-0"
            >
              Breakpoint with sticky sidebar
            </h3>
            <sgds-table
              tableBorder
              headerBackground
              responsive="always"
              class="typography-page-template__utility-table"
            >
              <sgds-table-row>
                <sgds-table-head :class="tokenColumnClass"
                  >Token</sgds-table-head
                >
                <sgds-table-head :class="valueColumnClass"
                  >Screen size</sgds-table-head
                >
                <sgds-table-head :class="valueColumnClass"
                  >Container width</sgds-table-head
                >
                <sgds-table-head :class="numericColumnClass"
                  >Columns</sgds-table-head
                >
                <sgds-table-head :class="numericColumnClass"
                  >Gutters</sgds-table-head
                >
                <sgds-table-head :class="valueColumnClass"
                  >Outer margins</sgds-table-head
                >
                <sgds-table-head :class="valueColumnClass"
                  >Side nav width</sgds-table-head
                >
              </sgds-table-row>

              <sgds-table-row
                v-for="row in stickySidebarTokens"
                :key="row.token"
              >
                <sgds-table-cell :class="tokenColumnClass">
                  <CodeToken :label="`--${row.token}`" />
                </sgds-table-cell>
                <sgds-table-cell :class="valueColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.screenSize }}
                  </span>
                </sgds-table-cell>
                <sgds-table-cell :class="valueColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.containerWidth }}
                  </span>
                </sgds-table-cell>
                <sgds-table-cell :class="numericColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.columns }}
                  </span>
                </sgds-table-cell>
                <sgds-table-cell :class="numericColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.gutters }}
                  </span>
                </sgds-table-cell>
                <sgds-table-cell :class="valueColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.outerMargins }}
                  </span>
                </sgds-table-cell>
                <sgds-table-cell :class="valueColumnClass">
                  <span
                    class="sgds:text-body-md sgds:font-regular sgds:leading-xs sgds:tracking-normal"
                  >
                    {{ row.sideNavWidth }}
                  </span>
                </sgds-table-cell>
              </sgds-table-row>
            </sgds-table>
          </div>
        </div>
      </div>
    </section>
  </TypographyPageTemplate>
</template>

<style>
/* The screen-size diagram uses absolute-positioned DOM labels over an SVG.
 * Keep a readable minimum canvas width so nearby marker labels do not collide
 * on narrow viewports; the wrapper provides horizontal overflow instead. */
.br-screen-size-diagram-wrap {
  overflow-x: auto;
  overflow-y: hidden;
}

.br-screen-size-diagram {
  min-inline-size: var(--sgds-dimension-1024);
}
</style>
